[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$SandboxBuildRoot,[Parameter(Mandatory=$false)][string]$OutputRoot=(Join-Path $PSScriptRoot '..\..\release\stellar-v0.1-d4-v02-review-envelope'))
$ErrorActionPreference='Stop';$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..\..')).Path;$out=[IO.Path]::GetFullPath($OutputRoot)
if(-not $out.StartsWith($repo,[StringComparison]::OrdinalIgnoreCase)){throw 'D4_OUTPUT_OUTSIDE_REPOSITORY'};if((Test-Path $out) -and (Test-Path (Join-Path $out 'release-envelope.v0.2.canonical.json'))){throw 'D4_RELEASE_ALREADY_EXISTS'}
$utf8NoBom=[Text.UTF8Encoding]::new($false)
function Get-Sha256Hex([byte[]]$bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Get-VerifiedT7bSourceHash([string]$path){$src=(Resolve-Path -LiteralPath $path).Path;$item=Get-Item -LiteralPath $src -Force;if($item.PSIsContainer -or $item.Attributes -band [IO.FileAttributes]::ReparsePoint -or $item.LinkType){throw "D4_T7B_SOURCE_REFUSED: $src"};return Get-Sha256Hex ([IO.File]::ReadAllBytes($src))}
function Assert-CopiedT7bRuntimeBinding([string]$relative,[string]$expected,[string]$failure){$actual=Get-VerifiedT7bSourceHash (Join-Path $out $relative);if($actual -cne $expected){throw $failure}}
$v=Join-Path $repo 'native\stellar\v0_1';$acceptance=Get-Content -LiteralPath "$v\evidence\t7b-target-host-acceptance.json" -Raw|ConvertFrom-Json;$bindings=$acceptance.bindings
if($null -eq $bindings -or [string]::IsNullOrWhiteSpace([string]$bindings.brokerSha256) -or [string]::IsNullOrWhiteSpace([string]$bindings.runnerSha256)){throw 'D4_T7B_ACCEPTANCE_BINDINGS_INVALID'}
$sandboxBrokerHash=Get-VerifiedT7bSourceHash (Join-Path $SandboxBuildRoot 'stellar-t7b-sandbox.exe');$sandboxRunnerHash=Get-VerifiedT7bSourceHash (Join-Path $SandboxBuildRoot 'stellar-t7b-fixed-probe.exe')
if($sandboxBrokerHash -cne [string]$bindings.brokerSha256){throw 'D4_T7B_BROKER_HASH_MISMATCH'};if($sandboxRunnerHash -cne [string]$bindings.runnerSha256){throw 'D4_T7B_RUNNER_HASH_MISMATCH'}
$vswhere='C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe';$vs=& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath|Select-Object -First 1;$dev=Join-Path $vs 'Common7\Tools\VsDevCmd.bat';$envLines=& $env:ComSpec /d /s /c ('call "'+$dev+'" -arch=x64 -host_arch=x64 >nul && set');foreach($line in $envLines){$at=$line.IndexOf('=');if($at -gt 0){[Environment]::SetEnvironmentVariable($line.Substring(0,$at),$line.Substring($at+1),'Process')}}
New-Item -ItemType Directory $out -Force|Out-Null;$entries=[Collections.Generic.List[object]]::new()
function Inspect-Pe([string]$path){$raw=& dumpbin.exe /nologo /imports $path;if($LASTEXITCODE){throw "D4_DUMPBIN_FAILED: $path"};$imports=[Collections.Generic.List[string]]::new();$dll='';foreach($line in $raw){if($line -match '^\s{4}([A-Za-z0-9_.-]+\.dll)\s*$'){$dll=$Matches[1].ToUpperInvariant()}elseif($dll -and $line -match '^\s+[0-9A-Fa-f]+\s+([A-Za-z_][^\s]*)\s*$'){$imports.Add("$dll!$($Matches[1])")}};[string[]]$unique=@($imports|Sort-Object -Unique);if(-not $unique.Count){throw "D4_EMPTY_NATIVE_IMPORTS: $path"};$sig=Get-AuthenticodeSignature -LiteralPath $path;$policy=if($sig.Status -eq 'Valid'){'REQUIRE_VALID_EMBEDDED'}else{'UNSIGNED_REVIEW_ONLY'};[string[]]$signers=@();if($sig.Status -eq 'Valid'){$signers=@('AUTHENTICODE:'+($sig.SignerCertificate.Thumbprint.ToUpperInvariant()))}else{$signers=@('AUTHENTICODE:UNSIGNED')};$inspection=[ordered]@{schema='stellar.t7d-native-pe-inspection/v0.1';imageSha256='sha256:'+((Get-FileHash $path).Hash.ToLower());tool='dumpbin.exe';imports=$unique;authenticodeStatus=$sig.Status.ToString();authenticodePolicy=$policy;signers=$signers};$json=$inspection|ConvertTo-Json -Depth 6 -Compress;return [ordered]@{imports=$unique;signers=$signers;authenticodePolicy=$policy;nativeInspectionHash='sha256:'+(Get-Sha256Hex ([Text.Encoding]::UTF8.GetBytes($json)));inspection=$inspection}}
function Add-File([string]$source,[string]$relative,[string]$kind,[bool]$pe=$false){$src=(Resolve-Path $source).Path;$item=Get-Item $src -Force;if($item.Attributes -band [IO.FileAttributes]::ReparsePoint -or $item.LinkType){throw "D4_SOURCE_LINK_REFUSED: $src"};$dest=Join-Path $out $relative;New-Item -ItemType Directory (Split-Path $dest) -Force|Out-Null;Copy-Item $src $dest;$i=if($pe){Inspect-Pe $dest}else{$null};[string[]]$entryImports=@();[string[]]$entrySigners=@();$entryPolicy=$null;$entryInspection=$null;if($pe){$entryImports=[string[]]$i.imports;$entrySigners=[string[]]$i.signers;$entryPolicy=$i.authenticodePolicy;$entryInspection=$i.nativeInspectionHash;$inspectionPath='inspection/'+([IO.Path]::GetFileName($dest))+'.native-inspection.json';$ip=Join-Path $out $inspectionPath;New-Item -ItemType Directory (Split-Path $ip) -Force|Out-Null;$inspectionJson=$i.inspection|ConvertTo-Json -Depth 8 -Compress;[IO.File]::WriteAllText($ip,$inspectionJson,$utf8NoBom);$entries.Add([ordered]@{path=$inspectionPath;kind='static-imports';imports=[string[]]@();signers=[string[]]@();authenticodePolicy=$null;nativeInspectionHash=$null})};$entries.Add([ordered]@{path=$relative.Replace('\','/');kind=$kind;imports=$entryImports;signers=$entrySigners;authenticodePolicy=$entryPolicy;nativeInspectionHash=$entryInspection})}
