Assert-CopiedT7bRuntimeBinding 'bin/stellar-t7b-sandbox.exe' ([string]$bindings.brokerSha256) 'D4_T7B_COPIED_BROKER_HASH_MISMATCH';Assert-CopiedT7bRuntimeBinding 'bin/stellar-t7b-fixed-probe.exe' ([string]$bindings.runnerSha256) 'D4_T7B_COPIED_RUNNER_HASH_MISMATCH'
Add-File "$repo\native\stellar\.out\phase-a-final\host\stellar-native-compiler.exe" 'bin/stellar-native-compiler.exe' 'compiler' $true;Add-File "$repo\native\stellar\.out\phase-a-final\run-1\stellar-native-runner.exe" 'bin/stellar-native-runner.exe' 'runner' $true
Add-File "$v\stdlib\stellar.stdlib.json" 'stdlib/stellar.stdlib.json' 'stdlib';Get-ChildItem "$v\schemas" -File|Sort Name|%{Add-File $_.FullName "schemas/$($_.Name)" 'schema'};Get-ChildItem "$v\service" -Filter '*.canonical.json' -File|Sort Name|%{Add-File $_.FullName "policy/$($_.Name)" 'canonical-policy'}
