Add-File "$v\service\t7d-d2-service-runtime.canonical.json" 'config/service-runtime.canonical.json' 'config';Add-File "$v\service\service-contract-adapter.ts" 'adapter/service-contract-adapter.ts' 'adapter';Add-File "$v\service\d4-installer-model.ts" 'scripts/d4-installer-model.ts' 'script';Add-File "$v\service\d4-release-package.ts" 'scripts/d4-release-package.ts' 'script';Add-File "$repo\server\stellar-capability-contract.ts" 'scripts/stellar-capability-contract.ts' 'script';Get-ChildItem "$v\service\tools" -File|Sort Name|%{Add-File $_.FullName "scripts/$($_.Name)" 'script'};Get-ChildItem "$repo\docs" -Filter 'STELLAR_WINDOWS_X64_V0_1_*.md' -File|Sort Name|%{Add-File $_.FullName "docs/$($_.Name)" 'documentation'}
