$inventory=Join-Path $out '.inventory.json';$inventoryJson=[ordered]@{releaseId='stellar-v0.1-d4-v02-review';files=@($entries|Sort path)}|ConvertTo-Json -Depth 10;[IO.File]::WriteAllText($inventory,$inventoryJson,$utf8NoBom)
npx tsx "$PSScriptRoot\finalize-d4-v02-release.ts" $out $inventory ([string]$bindings.brokerSha256) ([string]$bindings.runnerSha256);if($LASTEXITCODE){throw 'D4_FINALIZE_FAILED'};Remove-Item $inventory;Get-ChildItem $out -Recurse -File|%{$_.IsReadOnly=$true}
